import hashlib, itertools, string, multiprocessing as mp

TARGET = bytes.fromhex('155fb95d04287b757c996d77b5ea51f7')
ALNUM = string.ascii_letters + string.digits

def worker(first):
    # check short lengths for this first letter
    for L in range(1, 5):
        for t in itertools.product(ALNUM, repeat=L-1):
            s = first + ''.join(t)
            if hashlib.md5(s.encode()).digest() == TARGET:
                return s
    # the 5-char space: this first letter + 4 more
    for t in itertools.product(ALNUM, repeat=4):
        s = first + ''.join(t)
        if hashlib.md5(s.encode()).digest() == TARGET:
            return s
    return None

if __name__ == '__main__':
    with mp.Pool(20) as pool:
        for r in pool.imap_unordered(worker, list(ALNUM)):
            if r:
                print('FOUND:', r)
                pool.terminate()
                break
        else:
            print('not found')
CRACKEOF
